SELECT CASE WHEN budget >= 3915000 THEN 'high' WHEN budget >= 1689000 THEN 'mid' ELSE 'low' END AS budget_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(dept_name))) AS dept_name_values, SUM(budget) AS total_budget, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(location))) AS location_values FROM departments GROUP BY CASE WHEN budget >= 3915000 THEN 'high' WHEN budget >= 1689000 THEN 'mid' ELSE 'low' END HAVING SUM(budget) >= 21193000;
